    await close();
    throw error;
  } finally {
    for (const [key, value] of previous) {
      if (value === undefined) delete process.env[key]; else process.env[key] = value;
    }
  }
  try {await server.listen();} catch (error) {await close(); throw error;}
  return {server, cacheDir, close};
}

